102	static void volume_bar_event_cb(lv_event_t *e)
103	{
104	    lv_event_code_t code = lv_event_get_code(e);
105	    
106	    if (code == LV_EVENT_PRESSED || code == LV_EVENT_PRESSING) {
107	        // 获取触摸位置
108	        lv_point_t point;
109	        lv_indev_get_point(lv_indev_active(), &point);
110	        
111	        // 获取容器的位置和大小
112	        lv_area_t container_area;
113	        lv_obj_get_coords(lv_event_get_current_target(e), &container_area);
114	        
115	        // 计算容器内的相对坐标
116	        lv_point_t container_point;
117	        container_point.x = point.x - container_area.x1;
118	        container_point.y = point.y - container_area.y1;
119	        
120	        // 限制在容器范围内
121	        if (container_point.x < 0) container_point.x = 0;
122	        int container_width = lv_obj_get_width(volume_container);
123	        if (container_point.x > container_width) container_point.x = container_width;
124	        
125	        // 计算音量等级 (0-4)
126	        int new_level = (container_point.x * 5) / container_width;
127	        if (new_level < 0) new_level = 0;
128	        if (new_level > 4) new_level = 4;
129	        
130	        // 更新音量
131	        if (new_level != current_volume_level) {
132	            current_volume_level = new_level;
133	            lv_obj_t *container = lv_event_get_current_target(e);
134	            lv_obj_t *indicator = lv_obj_get_child(container, 0);
135	            if (indicator) {
136	                lv_obj_set_width(indicator, container_width * (current_volume_level + 1) / 5);
137	                lv_obj_align(indicator, LV_ALIGN_LEFT_MID, 0, 0);
138	            }
139	
140	            int vol_value = volume_level_to_value(current_volume_level);
141	            esp32s3_watch_audio_setvolume(vol_value);
142	
143	            printf("Set volume to level %d, value %d\n", current_volume_level, vol_value);
144	        }
145	    }
146	}
