148	/**
149	 * 滑动手势处理 - 音量调节页面
150	 */
151	static void slide_gesture_volume_set_handler(lv_event_t *e)
152	{
153	    lv_event_code_t code = lv_event_get_code(e);
154	
155	    static lv_point_t start_point = {0};
156	    static bool is_dragging = false;
157	
158	    switch(code) {
159	        case LV_EVENT_PRESSED:
160	            lv_indev_get_point(lv_indev_active(), &start_point);
161	            is_dragging = true;
162	            break;
163	        
164	        case LV_EVENT_RELEASED:
165	            if(is_dragging) {
166	                lv_point_t end_point;
167	                lv_indev_get_point(lv_indev_active(), &end_point);
168	                
169	                int32_t delta_x = end_point.x - start_point.x;
170	                int32_t delta_y = end_point.y - start_point.y;
171	
172	                if(delta_x > 50 && abs(delta_x) > abs(delta_y)) {
173	                    // 右滑：退出当前页面
174	                    esp32s3_watch_audio_stop();
175	                    if(volume_set_base != NULL) {
176	                        // 将页面从页面栈弹出
177	                        vw_watch_pop_page(volume_set_base);
178	                        // 删除页面
179	                        lv_obj_del(volume_set_base);
180	                        volume_set_base = NULL;
181	                    }
182	                }
183	            }
184	            is_dragging = false;
185	            break;
186	            
187	        default:
188	            break;
189	    }
190	}
