95	/* ── Tool: set_watch_volume ──────────────────────────────────── */
96	
97	int tool_watch_volume_set_execute(const char *input_json,
98	                                   char *output, size_t output_size)
99	{
100	    cJSON *root = cJSON_Parse(input_json);
101	    if (!root) {
102	        snprintf(output, output_size,
103	            "{\"error\":\"invalid JSON\"}");
104	        return ERROR;
105	    }
106	
107	    cJSON *level_item = cJSON_GetObjectItem(root, "level");
108	    cJSON *action_item = cJSON_GetObjectItem(root, "action");
109	    int ret;
110	
111	    if (level_item && cJSON_IsNumber(level_item)) {
112	        /* Direct level set: 0-4 or 1-5 (auto-detect) */
113	        int level = (int)level_item->valuedouble;
114	        /* If user says 1-5, map to 0-4 */
115	        if (level >= 1 && level <= 5) level = level - 1;
116	        if (level < 0) level = 0;
117	        if (level > 4) level = 4;
118	        ret = watch_volume_set_level(level);
119	        cJSON_Delete(root);
120	        if (ret == 0) {
121	            snprintf(output, output_size,
122	                "{\"ok\":true,\"level\":%d,\"label\":\"%s\"}",
123	                level, vol_labels[level]);
124	            return OK;
125	        }
126	    } else if (action_item && cJSON_IsString(action_item)) {
127	        /* Action: up / down / mute / unmute */
128	        const char *action = action_item->valuestring;
129	        cJSON_Delete(root);
130	
131	        if (strcmp(action, "up") == 0) {
132	            ret = watch_volume_step_up();
133	        } else if (strcmp(action, "down") == 0) {
134	            ret = watch_volume_step_down();
135	        } else if (strcmp(action, "mute") == 0) {
136	            ret = watch_volume_set_level(VOL_LEVEL_MUTE);
137	        } else if (strcmp(action, "unmute") == 0) {
138	            ret = watch_volume_set_level(VOL_LEVEL_MEDIUM);
139	        } else {
140	            snprintf(output, output_size,
141	                "{\"error\":\"action must be up/down/mute/unmute\"}");
142	            return ERROR;
143	        }
144	
145	        if (ret >= 0) {
146	            int new_level = watch_volume_get_level();
147	            snprintf(output, output_size,
148	                "{\"ok\":true,\"level\":%d,\"label\":\"%s\"}",
149	                new_level, vol_labels[new_level]);
150	            return OK;
151	        }
152	    } else {
153	        cJSON_Delete(root);
154	        snprintf(output, output_size,
155	            "{\"error\":\"need 'level' (0-4) or 'action' (up/down/mute/unmute)\"}");
156	        return ERROR;
157	    }
158	
159	    snprintf(output, output_size, "{\"error\":\"volume set failed\"}");
160	    return ERROR;
161	}
