41	/* ── speak ─────────────────────────────────────────────────────────── */
42	
43	int tool_speak_execute(const char *input_json, char *output, size_t output_size)
44	{
45	    cJSON *root = cJSON_Parse(input_json);
46	    if (!root) {
47	        snprintf(output, output_size, "{\"error\":\"invalid json\"}");
48	        return ERROR;
49	    }
50	
51	    cJSON *text = cJSON_GetObjectItem(root, "text");
52	    if (!cJSON_IsString(text) || !text->valuestring[0]) {
53	        snprintf(output, output_size, "{\"error\":\"text required\"}");
54	        cJSON_Delete(root);
55	        return ERROR;
56	    }
57	
58	    const char *txt = text->valuestring;
59	    size_t len = strlen(txt);
60	
61	    /* Text length check — warn if exceeding 200 chars */
62	    if (len > 200) {
63	        syslog(LOG_WARNING, "[emotion] speak text truncated: %zu > 200\n", len);
64	    }
65	
66	    /* Log only — TTS is deferred to dispatch_response for unified playback.
67	     * Playing TTS here would compete with the final LLM response TTS,
68	     * causing double-playback. */
69	    syslog(LOG_INFO, "[emotion] speak (deferred): %s\n", txt);
70	
71	    /* Store last speak text so the ReAct loop can use it as final
72	     * response, skipping the LLM text-wrap-up round (~5s savings). */
73	    extern char* s_speak_text;
74	    free(s_speak_text);
75	    s_speak_text = strdup(txt);
76	
77	    cJSON_Delete(root);
78	
79	    /* Build output with cJSON for proper string escaping */
80	    cJSON *r = cJSON_CreateObject();
81	    cJSON_AddStringToObject(r, "status", "ok");
82	    cJSON_AddStringToObject(r, "text", txt);
83	    char *s = cJSON_PrintUnformatted(r);
84	    cJSON_Delete(r);
85	    if (s) {
86	        strncpy(output, s, output_size - 1);
87	        output[output_size - 1] = '\0';
88	        free(s);
89	    }
90	    return OK;
91	}
