39	
40	int watch_volume_level_to_value(int level)
41	{
42	  if (level < 0)
43	    {
44	      level = 0;
45	    }
46	  if (level >= WATCH_VOLUME_LEVEL_COUNT)
47	    {
48	      level = WATCH_VOLUME_LEVEL_COUNT - 1;
49	    }
50	  return s_volume_levels[level];
51	}
