111	  if (value < 0)
112	    {
113	      value = 0;
114	    }
115	  if (value > 1000)
116	    {
117	      value = 1000;
118	    }
119	  int ret = esp32s3_watch_audio_setvolume((uint16_t)value);
120	  VOL_LOG("Set volume to %d (ret=%d)", value, ret);
121	  return (ret == OK) ? 0 : -1;
122	#else
123	  VOL_LOG("Audio not configured, cannot set volume");
124	  return -1;
125	#endif
