128	int watch_volume_step_up(void)
129	{
130	  int level = watch_volume_get_level();
131	  if (level < 0)
132	    {
133	      return -1;
134	    }
135	  if (level < WATCH_VOLUME_LEVEL_COUNT - 1)
136	    {
137	      level++;
138	      watch_volume_set_level(level);
139	    }
140	  return level;
141	}
