58	    {
59	      pthread_mutex_unlock(&g_audio_mutex);
60	      return -errno;
61	    }
62	
63	  cap_desc.caps.ac_len       = sizeof(struct audio_caps_s);
64	  cap_desc.caps.ac_type      = AUDIO_TYPE_FEATURE;
65	  cap_desc.caps.ac_format.hw = AUDIO_FU_VOLUME;
66	  cap_desc.caps.ac_controls.hw[0] = volume;
67	
68	  ret = ioctl(fd, AUDIOIOC_CONFIGURE, (unsigned long)&cap_desc);
