42	
43	/* Square-law mapping from percent to hardware value.
44	 * This spreads the quiet range (10-40%) and compresses the loud end,
45	 * matching human loudness perception better than linear mapping.
46	 *
47	 *   hw = 1000 * ((pct - 10) / 90)^2   (pct ≥ 10)
48	 *
49	 *   pct  10%   20%   30%   50%   70%   100%
50	 *   hw     0    12    49   198   444   1000
51	 *   DAC   85    92   144   196   226    255   (coeff=37)
52	 */
53	static int percent_to_hw(int percent)
54	{
55	  if (percent < WATCH_VOLUME_PERCENT_MIN)
56	    {
57	      return 0;
58	    }
59	  if (percent >= WATCH_VOLUME_PERCENT_MAX)
60	    {
61	      return WATCH_VOLUME_HW_MAX;
62	    }
63	  /* k = 2.0 for square-law: hw ∝ proportion^2 */
64	  int prop = percent - WATCH_VOLUME_PERCENT_MIN;  /* 0..90 */
65	  return (int)((int64_t)WATCH_VOLUME_HW_MAX * prop * prop /
66	               (90 * 90));
67	}
68	
69	/* Inverse of percent_to_hw: sqrt of hardware proportion */
70	static int hw_to_percent(int value)
71	{
72	  if (value <= 0)
73	    {
74	      return 0;
75	    }
76	  if (value >= WATCH_VOLUME_HW_MAX)
77	    {
78	      return WATCH_VOLUME_PERCENT_MAX;
79	    }
80	  /* sqrt(hw/1000) * 90 + 10 */
81	  return WATCH_VOLUME_PERCENT_MIN +
82	         (int)(90.0f * sqrtf((float)value / WATCH_VOLUME_HW_MAX));
83	}
