85	int watch_volume_set_percent(int percent)
86	{
87	  int hw = percent_to_hw(percent);
88	  int ret = watch_volume_set_value(hw);
89	  VOL_LOG("Set percent %d%% → hw=%d (ret=%d)", percent, hw, ret);
90	  return (ret == 0) ? 0 : -1;
91	}
