107	int watch_volume_step_delta(int delta)
108	{
109	  int pct = watch_volume_get_percent();
110	  if (pct < 0)
111	    {
112	      return -1;
113	    }
114	  pct += delta;
115	  if (pct < WATCH_VOLUME_PERCENT_MIN)
116	    {
117	      pct = WATCH_VOLUME_PERCENT_MIN;
118	    }
119	  if (pct > WATCH_VOLUME_PERCENT_MAX)
120	    {
121	      pct = WATCH_VOLUME_PERCENT_MAX;
122	    }
123	  watch_volume_set_percent(pct);
124	  return pct;
125	}
