1	/****************************************************************************
2	 * boards/xtensa/esp32s3/esp32s3-touch-amoled/src/esp32s3_watch_audio.c
3	 *
4	 * SPDX-License-Identifier: Apache-2.0
5	 ****************************************************************************/
6	
7	/****************************************************************************
8	 * Included Files
9	 ****************************************************************************/
10	
11	#include <nuttx/config.h>
12	
13	#include <stdio.h>
14	#include <fcntl.h>
15	#include <unistd.h>
16	#include <errno.h>
17	#include <sys/ioctl.h>
18	#include <pthread.h>
19	
20	#include <nuttx/audio/audio.h>
21	
22	#include <arch/board/board.h>
23	#include "esp32s3-touch-amoled.h"
24	
25	#if defined(CONFIG_ESP32S3_I2S) && defined(CONFIG_AUDIO_ES8311)
26	
27	/****************************************************************************
28	 * Private Data
29	 ****************************************************************************/
30	
31	#define AUDIO_DEVICE_PATH  "/dev/audio/pcm0"
32	
33	static uint16_t g_watch_volume = 500;
34	static pthread_mutex_t g_audio_mutex = PTHREAD_MUTEX_INITIALIZER;
35	static int g_audio_fd = -1;  /* persistent, opened once */
36	
37	/****************************************************************************
38	 * Public Functions
39	 ****************************************************************************/
40	
41	int esp32s3_watch_audio_setvolume(uint16_t volume)
42	{
43	  struct audio_caps_desc_s cap_desc;
44	  int ret;
45	
46	  if (volume > 1000)
47	    {
48	      volume = 1000;
49	    }
50	
51	  pthread_mutex_lock(&g_audio_mutex);
52	
53	  g_watch_volume = volume;
54	
55	  /* Open the audio device once and keep it open.  Previously we
56	   * opened/closed on every call, which could fail (or block) when
57	   * ASR/TTS holds a session on the same device, causing the agent
58	   * tool to hang and the "thinking" face to freeze.
59	   */
60	
61	  if (g_audio_fd < 0)
62	    {
63	      g_audio_fd = open(AUDIO_DEVICE_PATH, O_RDWR);
64	    }
65	
66	  if (g_audio_fd >= 0)
67	    {
68	      cap_desc.caps.ac_len       = sizeof(struct audio_caps_s);
69	      cap_desc.caps.ac_type      = AUDIO_TYPE_FEATURE;
70	      cap_desc.caps.ac_format.hw = AUDIO_FU_VOLUME;
71	      cap_desc.caps.ac_controls.hw[0] = volume;
72	
73	      ret = ioctl(g_audio_fd, AUDIOIOC_CONFIGURE,
74	                  (unsigned long)&cap_desc);
75	      if (ret < 0)
76	        {
77	          /* Device may have been closed underneath us — reopen next call */
78	          close(g_audio_fd);
79	          g_audio_fd = -1;
80	        }
81	    }
82	  else
83	    {
84	      ret = -errno;
85	    }
86	
87	  pthread_mutex_unlock(&g_audio_mutex);
88	
89	  return (ret < 0) ? -errno : OK;
90	}
91	
92	int esp32s3_watch_audio_getvolume(uint16_t *volume)
93	{
94	  if (volume == NULL)
95	    {
96	      return -EINVAL;
97	    }
98	
99	  pthread_mutex_lock(&g_audio_mutex);
100	  *volume = g_watch_volume;
101	  pthread_mutex_unlock(&g_audio_mutex);
102	
103	  return OK;
104	}
105	
106	#endif /* CONFIG_ESP32S3_I2S && CONFIG_AUDIO_ES8311 */
107

