66	
67	      ret = ioctl(fd, AUDIOIOC_CONFIGURE, (unsigned long)&cap_desc);
68	      close(fd);
69	    }
70	  else
71	    {
72	      ret = -errno;
73	    }
74	
75	  pthread_mutex_unlock(&g_audio_mutex);
