1	/**
2	 * @file volume_control.c
3	 * 音量控制模块实现
4	 *
5	 * 通过 ESP32-S3 I2S + ES8311 音频编解码器控制硬件音量。
6	 * 百分比 10-100% 线性映射到硬件范围 100-1000（<10% 视为静音=0）。
7	 */
8	
9	#include <nuttx/config.h>
10	#include <stdio.h>
11	#include <stdlib.h>
12	#include <string.h>
13	#include <unistd.h>
14	#include <stdbool.h>
15	#include <math.h>
16	
17	#include <arch/board/board.h>
18	
19	#include "volume_control.h"
20	
21	/****************************************************************************
22	 * Pre-processor Definitions
23	 ****************************************************************************/
24	
25	#define VOL_TAG "[VOLUME] "
26	#define VOL_LOG(fmt, ...)  /* disabled — printf blocks on console */
27	
28	#define WATCH_VOLUME_PERCENT_MIN  10
29	#define WATCH_VOLUME_PERCENT_MAX 100
30	#define WATCH_VOLUME_HW_MIN      100   /* hardware value for 10% */
31	#define WATCH_VOLUME_HW_MAX     1000   /* hardware value for 100% */
32	
33	/****************************************************************************
34	 * Private Data
35	 ****************************************************************************/
36	
37	static const int s_volume_levels[5] = {0, 250, 500, 750, 1000};
38	
39	/****************************************************************************
40	 * Public Functions — Percent API
41	 ****************************************************************************/
42	
43	/* Square-law mapping from percent to hardware value.
44	 * Spreads the quiet range and compresses the loud end to match
45	 * human loudness perception.
46	 *
47	 *   hw = 1000 * (pct / 100)^2     (0% → 0, 100% → 1000)
48	 *
49	 *   pct   0%   10%   20%   30%   50%   70%   100%
50	 *   hw     0    10    40    90   250   490   1000
51	 *   DAC    0    85   136   166   204   229    255
52	 */
53	static int percent_to_hw(int percent)
54	{
55	  if (percent <= 0)
56	    {
57	      return 0;
58	    }
59	  if (percent >= WATCH_VOLUME_PERCENT_MAX)
60	    {
61	      return WATCH_VOLUME_HW_MAX;
62	    }
63	  /* k = 2.0: hw ∝ percent^2 */
64	  return (int)((int64_t)WATCH_VOLUME_HW_MAX * percent * percent /
65	               (100 * 100));
66	}
67	
68	/* Inverse: sqrt of hardware proportion */
69	static int hw_to_percent(int value)
70	{
71	  if (value <= 0)
72	    {
73	      return 0;
74	    }
75	  if (value >= WATCH_VOLUME_HW_MAX)
76	    {
77	      return WATCH_VOLUME_PERCENT_MAX;
78	    }
79	  return (int)(100.0f * sqrtf((float)value / WATCH_VOLUME_HW_MAX));
80	}
81	
82	int watch_volume_set_percent(int percent)
83	{
84	  int hw = percent_to_hw(percent);
85	  int ret = watch_volume_set_value(hw);
86	  VOL_LOG("Set percent %d%% → hw=%d (ret=%d)", percent, hw, ret);
87	  return (ret == 0) ? 0 : -1;
88	}
89	
90	int watch_volume_get_percent(void)
91	{
92	#if defined(CONFIG_ESP32S3_I2S) && defined(CONFIG_AUDIO_ES8311)
93	  uint16_t vol = 0;
94	  if (esp32s3_watch_audio_getvolume(&vol) != OK)
95	    {
96	      return -1;
97	    }
98	  return hw_to_percent((int)vol);
99	#else
100	  return -1;
101	#endif
102	}
103	
104	int watch_volume_step_delta(int delta)
105	{
106	  int pct = watch_volume_get_percent();
107	  if (pct < 0)
108	    {
109	      return -1;
110	    }
111	  pct += delta;
112	  if (pct < WATCH_VOLUME_PERCENT_MIN)
113	    {
114	      pct = WATCH_VOLUME_PERCENT_MIN;
115	    }
116	  if (pct > WATCH_VOLUME_PERCENT_MAX)
117	    {
118	      pct = WATCH_VOLUME_PERCENT_MAX;
119	    }
120	  watch_volume_set_percent(pct);
121	  return pct;
122	}
123	
124	/****************************************************************************
125	 * Public Functions — Level API (backward compat)
126	 ****************************************************************************/
127	
128	int watch_volume_level_to_value(int level)
129	{
130	  if (level < 0) level = 0;
131	  if (level >= 5) level = 4;
132	  return s_volume_levels[level];
133	}
134	
135	int watch_volume_value_to_level(int value)
136	{
137	  if (value <= 0)   return 0;
138	  if (value <= 250) return 1;
139	  if (value <= 500) return 2;
140	  if (value <= 750) return 3;
141	  return 4;
142	}
143	
144	int watch_volume_get_level(void)
145	{
146	  int pct = watch_volume_get_percent();
147	  if (pct < 0) return -1;
148	  if (pct <= 0)   return 0;
149	  if (pct <= 25)  return 1;
150	  if (pct <= 50)  return 2;
151	  if (pct <= 75)  return 3;
152	  return 4;
153	}
154	
155	int watch_volume_set_level(int level)
156	{
157	  int value = watch_volume_level_to_value(level);
158	  return watch_volume_set_value(value);
159	}
160	
161	int watch_volume_get_value(void)
162	{
163	#if defined(CONFIG_ESP32S3_I2S) && defined(CONFIG_AUDIO_ES8311)
164	  uint16_t vol = 0;
165	  if (esp32s3_watch_audio_getvolume(&vol) != OK)
166	    {
167	      return -1;
168	    }
169	  return (int)vol;
170	#else
171	  return -1;
172	#endif
173	}
174	
175	int watch_volume_set_value(int value)
176	{
177	#if defined(CONFIG_ESP32S3_I2S) && defined(CONFIG_AUDIO_ES8311)
178	  if (value < 0)   value = 0;
179	  if (value > 1000) value = 1000;
180	  int ret = esp32s3_watch_audio_setvolume((uint16_t)value);
181	  VOL_LOG("Set volume to %d (ret=%d)", value, ret);
182	  return (ret == OK) ? 0 : -1;
183	#else
184	  VOL_LOG("Audio not configured, cannot set volume");
185	  return -1;
186	#endif
187	}
188	
189	int watch_volume_step_up(void)
190	{
191	  return watch_volume_step_delta(10);
192	}
193	
194	int watch_volume_step_down(void)
195	{
196	  return watch_volume_step_delta(-10);
197	}
198
